DROP TABLE IF EXISTS `posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `author_id` bigint unsigned NOT NULL COMMENT '作者用户ID',
  `title` varchar(200) DEFAULT NULL COMMENT '帖子标题',
  `content` text NOT NULL COMMENT '帖子内容',
  `images` json DEFAULT NULL COMMENT '图片URL数组',
  `tags` json DEFAULT NULL COMMENT '话题标签数组',
  `likes_count` int NOT NULL DEFAULT '0' COMMENT '点赞数',
  `comments_count` int NOT NULL DEFAULT '0' COMMENT '评论数',
  `share_count` int NOT NULL DEFAULT '0' COMMENT '转发数',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览量（详情读取原子 +1）',
  `hot_score` double NOT NULL DEFAULT '0' COMMENT '热度分（定时任务重算）',
  `hot_boost` double NOT NULL DEFAULT '1' COMMENT '运营热度倍率（默认1.0，>1上榜加成，0压榜）',
  `hot_banned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '禁止上榜（1=不上榜，不影响前台可见）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `audit_status` varchar(16) NOT NULL DEFAULT 'approved' COMMENT '审核状态: pending/approved/rejected',
  `activity_id` bigint DEFAULT NULL COMMENT '关联活动ID（activities.id，可为空）',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注（拒绝原因等）',
  `auditor_id` bigint unsigned DEFAULT NULL COMMENT '审核人用户 ID',
  `audited_at` datetime DEFAULT NULL COMMENT '审核时间',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  `category` varchar(32) NOT NULL DEFAULT 'all' COMMENT '分类',
  `status` varchar(32) NOT NULL DEFAULT 'active' COMMENT '状态',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否置顶（管理后台维护，村口列表置顶优先）',
  `owner_circle_path` varchar(256) DEFAULT NULL,
  `visibility` varchar(20) NOT NULL DEFAULT 'public' COMMENT '帖子可见范围：public=全校, school=同校, interest=同兴趣圈',
  `circle_id` bigint DEFAULT NULL COMMENT '关联兴趣圈 ID（visibility=interest 时必填）',
  PRIMARY KEY (`id`),
  KEY `idx_posts_author` (`author_id`),
  KEY `idx_posts_created_at` (`created_at`),
  KEY `idx_posts_audit_status` (`audit_status`),
  KEY `idx_posts_author_created_at` (`author_id`,`created_at`),
  KEY `idx_posts_status_created_at` (`created_at`),
  KEY `idx_posts_category` (`category`),
  KEY `idx_posts_status` (`status`),
  KEY `idx_posts_activity` (`activity_id`),
  KEY `idx_posts_hot_score` (`hot_score`),
  KEY `idx_posts_visibility` (`visibility`,`status`,`created_at`),
  CONSTRAINT `chk_posts_category` CHECK ((`category` in (_utf8mb4'all',_utf8mb4'interest',_utf8mb4'sincere',_utf8mb4'hometown',_utf8mb4'anonymous',_utf8mb4'latest',_utf8mb4'campus',_utf8mb4'activity'))),
  CONSTRAINT `chk_posts_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'deleted',_utf8mb4'hidden')))
) ENGINE=InnoDB AUTO_INCREMENT=415 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='村口帖子表';
